CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,display_name VARCHAR(100) NOT NULL DEFAULT '',status VARCHAR(20) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,display_name VARCHAR(100) NOT NULL DEFAULT '',role VARCHAR(30) NOT NULL DEFAULT 'admin',status VARCHAR(20) NOT NULL DEFAULT 'active',last_login_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,description TEXT NOT NULL,traffic VARCHAR(100) NOT NULL,region VARCHAR(100) NOT NULL,device_limit INT UNSIGNED NOT NULL DEFAULT 1,duration_days INT UNSIGNED NOT NULL,price_cents BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',sort_order INT NOT NULL DEFAULT 0,created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY idx_product_status_sort(status,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_plans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,duration_days INT UNSIGNED NOT NULL,price_cents BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',sort_order INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uk_product_plan_name(product_id,name),KEY idx_product_plan_status(product_id,status,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_no VARCHAR(40) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NULL,product_plan_id BIGINT UNSIGNED NULL,product_name_snapshot VARCHAR(160) NOT NULL,plan_name_snapshot VARCHAR(100) NOT NULL DEFAULT '',product_description_snapshot TEXT NOT NULL,traffic_snapshot VARCHAR(100) NOT NULL,region_snapshot VARCHAR(100) NOT NULL,device_limit_snapshot INT UNSIGNED NOT NULL,duration_days_snapshot INT UNSIGNED NOT NULL,unit_price_cents_snapshot BIGINT UNSIGNED NOT NULL,total_amount_cents BIGINT UNSIGNED NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending_payment',customer_note VARCHAR(500) NOT NULL DEFAULT '',payment_started_at DATETIME NULL,cancelled_at DATETIME NULL,cancelled_by_type VARCHAR(20) NULL,cancelled_by_id BIGINT UNSIGNED NULL,cancel_reason VARCHAR(500) NOT NULL DEFAULT '',refund_requested_at DATETIME NULL,refund_processed_at DATETIME NULL,refund_reason VARCHAR(500) NOT NULL DEFAULT '',temporary_subscription_url VARCHAR(500) NOT NULL DEFAULT '',temporary_subscription_status VARCHAR(20) NOT NULL DEFAULT 'none',temporary_subscription_issued_at DATETIME NULL,temporary_subscription_revoked_at DATETIME NULL,created_at DATETIME NOT NULL,paid_at DATETIME NULL,delivered_at DATETIME NULL,updated_at DATETIME NOT NULL,KEY idx_order_user(user_id,created_at),KEY idx_order_status(status,created_at),KEY idx_order_plan(product_plan_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,method VARCHAR(40) NOT NULL DEFAULT 'manual',amount_cents BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',confirmed_by BIGINT UNSIGNED NULL,confirmed_at DATETIME NULL,gateway_trade_no VARCHAR(100) NOT NULL DEFAULT '',gateway_order_no VARCHAR(64) NOT NULL DEFAULT '',gateway_type VARCHAR(20) NOT NULL DEFAULT '',payment_url VARCHAR(1000) NOT NULL DEFAULT '',paid_at DATETIME NULL,notify_payload TEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY idx_payment_order(order_id),KEY idx_payment_gateway_trade(gateway_trade_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS delivery_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,version_no INT UNSIGNED NOT NULL,action VARCHAR(20) NOT NULL,content_ciphertext MEDIUMTEXT NOT NULL,content_nonce VARBINARY(32) NOT NULL,content_tag VARBINARY(32) NOT NULL,content_preview VARCHAR(255) NOT NULL DEFAULT '',is_current TINYINT(1) NOT NULL DEFAULT 1,opened_at DATETIME NULL,expires_at DATETIME NULL,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uk_delivery_version(order_id,version_no),KEY idx_delivery_current(order_id,is_current)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS support_tickets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ticket_no VARCHAR(40) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NULL,subject VARCHAR(200) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'open',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,closed_at DATETIME NULL,KEY idx_ticket_user(user_id,updated_at),KEY idx_ticket_status(status,updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ticket_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ticket_id BIGINT UNSIGNED NOT NULL,sender_type VARCHAR(20) NOT NULL,sender_user_id BIGINT UNSIGNED NULL,sender_admin_id BIGINT UNSIGNED NULL,body TEXT NOT NULL,created_at DATETIME NOT NULL,KEY idx_message_ticket(ticket_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT UNSIGNED NOT NULL,action VARCHAR(80) NOT NULL,target_type VARCHAR(40) NOT NULL,target_id BIGINT UNSIGNED NULL,details_json LONGTEXT NULL,created_at DATETIME NOT NULL,KEY idx_log_admin(admin_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS articles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,category VARCHAR(40) NOT NULL DEFAULT '使用教程',summary VARCHAR(500) NOT NULL DEFAULT '',content TEXT NOT NULL,cover_style VARCHAR(30) NOT NULL DEFAULT 'blue',status VARCHAR(20) NOT NULL DEFAULT 'draft',published_at DATETIME NULL,created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY idx_article_status_publish(status,published_at),KEY idx_article_updated(updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS download_resources (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,app_name VARCHAR(80) NOT NULL,version VARCHAR(60) NOT NULL DEFAULT '',description VARCHAR(500) NOT NULL DEFAULT '',project_url VARCHAR(500) NOT NULL,platform VARCHAR(20) NOT NULL,filename VARCHAR(120) NOT NULL,source_url VARCHAR(500) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',sort_order INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uk_download_resource(app_name,platform,filename),KEY idx_download_status_platform(status,platform,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,gateway_url VARCHAR(500) NOT NULL DEFAULT 'https://pae.fksqy.cn/',pid VARCHAR(40) NOT NULL DEFAULT '',md5_key_ciphertext MEDIUMTEXT NOT NULL,md5_key_nonce VARBINARY(32) NOT NULL,md5_key_tag VARBINARY(32) NOT NULL,enabled TINYINT(1) NOT NULL DEFAULT 0,alipay_enabled TINYINT(1) NOT NULL DEFAULT 1,wechat_enabled TINYINT(1) NOT NULL DEFAULT 1,notify_base_url VARCHAR(500) NOT NULL DEFAULT '',updated_by BIGINT UNSIGNED NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS system_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(80) NOT NULL UNIQUE,setting_value VARCHAR(1000) NOT NULL DEFAULT '',updated_by BIGINT UNSIGNED NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,event_type VARCHAR(40) NOT NULL,old_status VARCHAR(30) NULL,new_status VARCHAR(30) NULL,description VARCHAR(500) NOT NULL,actor_type VARCHAR(20) NOT NULL,actor_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,KEY idx_order_event(order_id,created_at),KEY idx_order_event_type(event_type,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,type VARCHAR(40) NOT NULL,title VARCHAR(200) NOT NULL,content VARCHAR(1000) NOT NULL,order_no VARCHAR(40) NULL,read_at DATETIME NULL,created_at DATETIME NOT NULL,KEY idx_notification_user(user_id,read_at,created_at),KEY idx_notification_order(order_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
